	e = s.DB.QueryRow(`SELECT COALESCE(GREATEST(0,EXTRACT(EPOCH FROM ($2::timestamptz-min(GREATEST(created_at,run_at))))),0) FROM jobs WHERE `+where+`=$1 AND state='queued'`, arg, now).Scan(&age)
