	var n int
	e2 := s.DB.QueryRow(`SELECT count(*) FROM jobs WHERE `+where+`=$1 AND state='succeeded' AND finished_at >= $2`, arg, now.Add(-time.Hour)).Scan(&n)
	m["throughput_last_hour"] = n
	if e != nil {
		return nil, e
	}
	return m, e2
